#include "ragekit/meta.h"
#include "ragekit/hash.h"
#include "ragekit/rsc.h"
#include <algorithm>
#include <cstdio>

namespace rk {

namespace {

constexpr uint32_t kMetaVFT = 0x405bc808;
constexpr size_t   kRootSize = 112;
constexpr size_t   kMaxBlock = 0x4000; // CodeWalker's MetaBuilder.MaxBlockLength

[[noreturn]] void fail(const char* fmt, uint64_t a = 0, uint64_t b = 0) {
    char buf[200];
    std::snprintf(buf, sizeof buf, fmt, (unsigned long long)a, (unsigned long long)b);
    throw Error(buf);
}

// --- built-in tables (generated by tools/gen_meta_tables.py) ---------------------------------
struct GenEntry { uint32_t name; int32_t offset; uint8_t type; uint8_t unknown9; int16_t ref_index; uint32_t ref_key; };
struct GenStruct { uint32_t name, key, unknown8; int32_t size; int first, count; };
struct GenEnumEntry { uint32_t name; int32_t value; };
struct GenEnum { uint32_t name, key; int first, count; };
#include "meta_tables.inc"

struct Tables {
    std::vector<MetaStruct> structs;
    std::vector<MetaEnum> enums;
    Tables() {
        for (auto& g : kGenStructs) {
            bool dup = false;
            for (auto& s : structs) if (s.name == g.name) dup = true;
            if (dup) continue;
            MetaStruct s;
            s.name = g.name; s.key = g.key; s.unknown8 = g.unknown8; s.size = g.size;
            for (int i = 0; i < g.count; i++) {
                auto& e = kGenEntries[g.first + i];
                s.entries.push_back({e.name, e.offset, e.type, e.unknown9, e.ref_index, e.ref_key});
            }
            structs.push_back(std::move(s));
        }
        for (auto& g : kGenEnums) {
            bool dup = false;
            for (auto& e : enums) if (e.name == g.name) dup = true;
            if (dup) continue;
            MetaEnum e;
            e.name = g.name; e.key = g.key;
            for (int i = 0; i < g.count; i++) e.entries.push_back({kGenEnumEntries[g.first + i].name, kGenEnumEntries[g.first + i].value});
            enums.push_back(std::move(e));
        }
    }
};
const Tables& tables() { static const Tables t; return t; }

} // namespace

const MetaStruct* known_struct(uint32_t h) {
    for (auto& s : tables().structs) if (s.name == h) return &s;
    return nullptr;
}
const MetaEnum* known_enum(uint32_t h) {
    for (auto& e : tables().enums) if (e.name == h) return &e;
    return nullptr;
}

// --- Meta -------------------------------------------------------------------------------------

const MetaStruct* Meta::find_struct(uint32_t h) const {
    for (auto& s : structs) if (s.name == h) return &s;
    return nullptr;
}
const MetaEnum* Meta::find_enum(uint32_t h) const {
    for (auto& e : enums) if (e.name == h) return &e;
    return nullptr;
}
const MetaBlock* Meta::find_block(uint32_t type) const {
    for (auto& b : blocks) if (b.type == type) return &b;
    return nullptr;
}
const MetaBlock* Meta::root() const {
    return root_block >= 1 && (size_t)root_block <= blocks.size() ? &blocks[root_block - 1] : nullptr;
}
const MetaBlock& Meta::block(uint32_t id) const {
    if (id < 1 || id > blocks.size()) fail("meta pointer to block %llu, file has %llu blocks", id, blocks.size());
    return blocks[id - 1];
}
const uint8_t* Meta::at(uint64_t pointer, size_t need) const {
    const MetaBlock& b = block(meta_block_id(pointer));
    uint64_t off = meta_offset(pointer);
    if (off + need > b.data.size()) fail("meta pointer offset %llu runs past its block (%llu bytes)", off + need, b.data.size());
    return b.data.data() + off;
}
std::span<const uint8_t> Meta::array_bytes(const MetaArray& a, size_t stride) const {
    if (a.pointer == 0 || a.count == 0) return {};
    return {at(a.pointer, stride * a.count), stride * a.count};
}
std::string Meta::string_at(uint64_t pointer) const {
    if (pointer == 0) return {};
    const MetaBlock& b = block(meta_block_id(pointer));
    uint64_t off = meta_offset(pointer);
    std::string s;
    while (off < b.data.size() && b.data[off]) s.push_back((char)b.data[off++]);
    return s;
}
MetaArray Meta::read_array(const uint8_t* p) {
    MetaArray a;
    std::memcpy(&a.pointer, p, 8);
    std::memcpy(&a.count, p + 8, 2);
    std::memcpy(&a.capacity, p + 10, 2);
    std::memcpy(&a.unknown, p + 12, 4);
    return a;
}

// --- reading ----------------------------------------------------------------------------------

Meta read_meta(std::span<const uint8_t> file) {
    rsc::Resource res = rsc::Resource::load(file);
    Reader r(res);
    constexpr uint64_t P = rsc::kSystemBase;
    if (res.system.size() < kRootSize) throw Error("meta: system segment too small");
    auto c = r.cursor(P + 16);
    Meta m;
    m.signature = c.u32();
    if (m.signature != 0x50524430) fail("meta: unexpected signature 0x%llX (a PSO-style meta file is not supported)", m.signature);
    m.header_version = c.u16();
    m.has_encrypted_strings = c.u8() != 0;
    m.unknown17 = c.u8();
    m.unknown18 = c.u32();
    m.root_block = (int32_t)c.u32();
    uint64_t sip = c.u64(), eip = c.u64(), dbp = c.u64(), nmp = c.u64(), esp = c.u64();
    uint16_t sic = c.u16(), eic = c.u16(), dbc = c.u16();
    m.unknown4e = c.u16();
    for (auto& u : m.unknown50) u = c.u32();

    m.name = r.str(nmp);

    for (uint16_t i = 0; i < sic; i++) {
        auto s = r.cursor(sip + i * 32ull);
        MetaStruct ms;
        ms.name = s.u32(); ms.key = s.u32(); ms.unknown8 = s.u32(); ms.unknownC = s.u32();
        uint64_t ep = s.u64();
        ms.size = (int32_t)s.u32();
        ms.unknown1C = s.u16();
        uint16_t ec = s.u16();
        for (uint16_t k = 0; k < ec; k++) {
            auto e = r.cursor(ep + k * 16ull);
            MetaEntry me;
            me.name = e.u32(); me.offset = (int32_t)e.u32(); me.type = e.u8(); me.unknown9 = e.u8();
            me.ref_index = e.i16(); me.ref_key = e.u32();
            ms.entries.push_back(me);
        }
        m.structs.push_back(std::move(ms));
    }
    for (uint16_t i = 0; i < eic; i++) {
        auto s = r.cursor(eip + i * 24ull);
        MetaEnum me;
        me.name = s.u32(); me.key = s.u32();
        uint64_t ep = s.u64();
        uint32_t ec = s.u32();
        me.unknown14 = (int32_t)s.u32();
        for (uint32_t k = 0; k < ec; k++) {
            auto e = r.cursor(ep + k * 8ull);
            MetaEnumEntry en;
            en.name = e.u32(); en.value = (int32_t)e.u32();
            me.entries.push_back(en);
        }
        m.enums.push_back(std::move(me));
    }
    for (uint16_t i = 0; i < dbc; i++) {
        auto s = r.cursor(dbp + i * 16ull);
        MetaBlock b;
        b.type = s.u32();
        uint32_t len = s.u32();
        uint64_t dp = s.u64();
        if (len) b.data = r.bytes(dp, len);
        m.blocks.push_back(std::move(b));
    }
    if (esp) {
        // big-endian byte count, then that many bytes
        uint32_t n = r.u32(esp);
        n = (n >> 24) | ((n >> 8) & 0xFF00) | ((n << 8) & 0xFF0000) | (n << 24);
        m.encrypted_strings = r.bytes(esp, 4 + (size_t)n);
    }
    return m;
}

// --- writing ----------------------------------------------------------------------------------

Bytes write_meta(const Meta& m, bool compress) {
    if (m.structs.size() > 0x7FFF || m.enums.size() > 0x7FFF || m.blocks.size() > 0x7FFF)
        throw Error("meta: too many structures / enums / blocks");
    Builder b;
    BlockId root = b.alloc(Segment::System, kRootSize);
    BlockId pages = b.alloc_pages_info();

    BlockId sinfo, einfo, dinfo, name, enc;
    if (!m.structs.empty()) {
        sinfo = b.alloc(Segment::System, m.structs.size() * 32);
        BlockWriter w(b, sinfo);
        for (auto& s : m.structs) {
            BlockId ent;
            if (!s.entries.empty()) {
                ent = b.alloc(Segment::System, s.entries.size() * 16);
                BlockWriter ew(b, ent);
                for (auto& e : s.entries) {
                    ew.u32(e.name); ew.u32((uint32_t)e.offset); ew.u8(e.type); ew.u8(e.unknown9);
                    ew.i16(e.ref_index); ew.u32(e.ref_key);
                }
            }
            w.u32(s.name); w.u32(s.key); w.u32(s.unknown8); w.u32(s.unknownC);
            w.ptr(ent);
            w.u32((uint32_t)s.size); w.u16(s.unknown1C); w.u16((uint16_t)s.entries.size());
        }
    }
    if (!m.enums.empty()) {
        einfo = b.alloc(Segment::System, m.enums.size() * 24);
        BlockWriter w(b, einfo);
        for (auto& e : m.enums) {
            BlockId ent;
            if (!e.entries.empty()) {
                ent = b.alloc(Segment::System, e.entries.size() * 8);
                BlockWriter ew(b, ent);
                for (auto& x : e.entries) { ew.u32(x.name); ew.u32((uint32_t)x.value); }
            }
            w.u32(e.name); w.u32(e.key); w.ptr(ent); w.u32((uint32_t)e.entries.size()); w.u32((uint32_t)e.unknown14);
        }
    }
    if (!m.blocks.empty()) {
        dinfo = b.alloc(Segment::System, m.blocks.size() * 16);
        BlockWriter w(b, dinfo);
        for (auto& blk : m.blocks) {
            BlockId d = b.array(Segment::System, blk.data);
            w.u32(blk.type); w.u32((uint32_t)blk.data.size()); w.ptr(d);
        }
    }
    if (!m.name.empty()) name = b.string(m.name);
    if (m.has_encrypted_strings && !m.encrypted_strings.empty()) enc = b.array(Segment::System, m.encrypted_strings);

    BlockWriter w(b, root);
    w.u32(kMetaVFT); w.u32(1); w.ptr(pages);
    w.u32(m.signature); w.u16(m.header_version); w.u8(m.has_encrypted_strings ? 1 : 0); w.u8(m.unknown17);
    w.u32(m.unknown18); w.u32((uint32_t)m.root_block);
    w.ptr(sinfo); w.ptr(einfo); w.ptr(dinfo); w.ptr(name); w.ptr(enc);
    w.u16((uint16_t)m.structs.size()); w.u16((uint16_t)m.enums.size()); w.u16((uint16_t)m.blocks.size());
    w.u16(m.unknown4e);
    for (uint32_t u : m.unknown50) w.u32(u);
    return b.build(rsc::kYtyp, compress);
}

// --- MetaBuilder --------------------------------------------------------------------------------

MetaBlock& MetaBuilder::ensure(uint32_t type) {
    for (auto& b : blocks_)
        if (b.type == type && b.data.size() < kMaxBlock) return b;
    blocks_.push_back(MetaBlock{type, {}});
    return blocks_.back();
}

static uint32_t block_id_of(const std::vector<MetaBlock>& blocks, const MetaBlock& b) {
    return (uint32_t)(&b - blocks.data()) + 1;
}

MetaPtr MetaBuilder::add_item_array(uint32_t type, std::span<const uint8_t> data, uint32_t count) {
    MetaBlock& blk = ensure(type);
    MetaPtr p;
    p.block_id = block_id_of(blocks_, blk);
    p.offset = (uint32_t)blk.data.size();
    p.length = count;
    blk.data.insert(blk.data.end(), data.begin(), data.end());
    blk.data.resize((blk.data.size() + 15) & ~size_t(15));
    return p;
}
MetaPtr MetaBuilder::add_item(uint32_t type, std::span<const uint8_t> data) {
    MetaPtr p = add_item_array(type, data, 1);
    p.length = (uint32_t)data.size();
    return p;
}
MetaPtr MetaBuilder::add_string(const std::string& s) {
    // CodeWalker packs strings back to back (no padding) in the string block.
    MetaBlock& blk = ensure(metatype::kString);
    MetaPtr p;
    p.block_id = block_id_of(blocks_, blk);
    p.offset = (uint32_t)blk.data.size();
    p.length = (uint32_t)s.size();
    blk.data.insert(blk.data.end(), s.begin(), s.end());
    blk.data.push_back(0);
    return p;
}
MetaPtr MetaBuilder::add_data_block(std::span<const uint8_t> data, uint32_t type) {
    blocks_.push_back(MetaBlock{type, Bytes(data.begin(), data.end())});
    MetaPtr p;
    p.block_id = (uint32_t)blocks_.size();
    p.offset = 0;
    p.length = (uint32_t)data.size();
    return p;
}
MetaPtr MetaBuilder::add_pointer_array(std::span<const uint64_t> ptrs) {
    if (ptrs.empty()) return {};
    return add_item_array(metatype::kPointer, {(const uint8_t*)ptrs.data(), ptrs.size() * 8}, (uint32_t)ptrs.size());
}
MetaPtr MetaBuilder::add_uint_array(std::span<const uint32_t> v, uint32_t type) {
    if (v.empty()) return {};
    return add_item_array(type, {(const uint8_t*)v.data(), v.size() * 4}, (uint32_t)v.size());
}
MetaPtr MetaBuilder::add_ushort_array(std::span<const uint16_t> v) {
    if (v.empty()) return {};
    return add_item_array(metatype::kUShort, {(const uint8_t*)v.data(), v.size() * 2}, (uint32_t)v.size());
}
MetaPtr MetaBuilder::add_byte_array(std::span<const uint8_t> v) {
    if (v.empty()) return {};
    return add_item_array(metatype::kByte, v, (uint32_t)v.size());
}
MetaPtr MetaBuilder::add_float_array(std::span<const float> v) {
    if (v.empty()) return {};
    return add_item_array(metatype::kFloat, {(const uint8_t*)v.data(), v.size() * 4}, (uint32_t)v.size());
}
MetaPtr MetaBuilder::add_padded_vec3_array(std::span<const Vec3> v, std::span<const float> w) {
    if (v.empty()) return {};
    Bytes d(v.size() * 16);
    for (size_t i = 0; i < v.size(); i++) {
        float f[4] = {v[i].x, v[i].y, v[i].z, i < w.size() ? w[i] : 0.0f};
        std::memcpy(d.data() + i * 16, f, 16);
    }
    return add_item_array(metatype::kVector4, d, (uint32_t)v.size());
}

void MetaBuilder::use_struct(const MetaStruct& s) {
    for (auto& x : structs_) if (x.name == s.name) return;
    structs_.push_back(s);
}
void MetaBuilder::use_enum(const MetaEnum& e) {
    for (auto& x : enums_) if (x.name == e.name) return;
    enums_.push_back(e);
}
void MetaBuilder::use_struct(uint32_t h) {
    for (auto& x : structs_) if (x.name == h) return;
    const MetaStruct* s = known_struct(h);
    if (!s) fail("meta: no built-in description for structure 0x%llX", h);
    structs_.push_back(*s);
}
void MetaBuilder::use_enum(uint32_t h) {
    for (auto& x : enums_) if (x.name == h) return;
    const MetaEnum* e = known_enum(h);
    if (!e) fail("meta: no built-in description for enum 0x%llX", h);
    enums_.push_back(*e);
}

namespace {
// Adds `name` and, through its entries, every structure / enum it needs. A block type may fall
// back to the built-in description; what a structure embeds is described from the source file's
// own tables when it brought some (game files often leave those out, and the game does not mind),
// from the built-in tables otherwise.
void register_tree(uint32_t name, bool nested, const std::vector<MetaStruct>* ps, const std::vector<MetaEnum>* pe,
                   std::vector<MetaStruct>& structs, std::vector<MetaEnum>& enums) {
    for (auto& s : structs) if (s.name == name) return;
    const bool from_source = ps && !ps->empty();
    const MetaStruct* found = nullptr;
    if (ps) for (auto& s : *ps) if (s.name == name) { found = &s; break; }
    if (!found && (!nested || !from_source)) found = known_struct(name);
    if (!found) return; // not a structure (a string / array block) or unknown: nothing to describe
    structs.push_back(*found);
    MetaStruct copy = *found;
    for (auto& e : copy.entries) {
        // Structures embedded in this one need a description of their own (they have no block);
        // array elements and pointed-to structures get theirs from their blocks.
        if (e.name != metatype::kArrayInfo && e.type == metatype::Structure && e.ref_key) {
            register_tree(e.ref_key, true, ps, pe, structs, enums);
        } else if ((e.type == metatype::IntEnum || e.type == metatype::ByteEnum || e.type == metatype::IntFlags1 ||
                    e.type == metatype::IntFlags2 || e.type == metatype::ShortFlags) && e.ref_key) {
            bool have = false;
            for (auto& x : enums) if (x.name == e.ref_key) have = true;
            if (have) continue;
            const MetaEnum* en = nullptr;
            if (pe) for (auto& x : *pe) if (x.name == e.ref_key) { en = &x; break; }
            if (!en && !from_source) en = known_enum(e.ref_key);
            if (en) enums.push_back(*en);
        }
    }
}
} // namespace

Meta MetaBuilder::finish(const std::string& name, const std::vector<MetaStruct>* ps, const std::vector<MetaEnum>* pe) const {
    Meta m;
    m.name = name;
    m.structs = structs_;
    m.enums = enums_;
    m.blocks = blocks_;
    for (auto& blk : blocks_) register_tree(blk.type, false, ps, pe, m.structs, m.enums);
    return m;
}

// --- detached objects -------------------------------------------------------------------------

namespace {

size_t primitive_stride(uint8_t t) {
    using namespace metatype;
    switch (t) {
        case Boolean: case SignedByte: case UnsignedByte: case ByteEnum: return 1;
        case SignedShort: case UnsignedShort: case ShortFlags: return 2;
        case SignedInt: case UnsignedInt: case Float: case Hash: case IntEnum: case IntFlags1: case IntFlags2: return 4;
        case Float_XYZ: case Float_XYZW: return 16; // stored padded to a vec4
        default: return 0;
    }
}

const MetaStruct* describe(const Meta& m, uint32_t type) {
    if (auto* s = m.find_struct(type)) return s;
    return known_struct(type);
}

struct Detacher {
    const Meta& m;
    MetaObject& obj;

    void zero_pointer(size_t at) {
        std::memset(obj.data.data() + at, 0, 8);
    }

    void walk(const MetaStruct& info, size_t base) {
        using namespace metatype;
        for (auto& e : info.entries) {
            if (e.name == kArrayInfo) continue;
            size_t at = base + (size_t)e.offset;
            switch (e.type) {
            case CharPointer: {
                MetaArray a = Meta::read_array(obj.data.data() + at);
                if (!a.pointer) break;
                MetaLink l; l.kind = MetaLink::Kind::String; l.offset = (uint32_t)at;
                const uint8_t* p = m.at(a.pointer, 0);
                if (a.count) { m.at(a.pointer, a.count); l.raw.assign(p, p + a.count); }
                else { std::string s = m.string_at(a.pointer); l.raw.assign(s.begin(), s.end()); }
                zero_pointer(at);
                obj.links.push_back(std::move(l));
                break;
            }
            case DataBlockPointer: {
                uint64_t ptr; std::memcpy(&ptr, obj.data.data() + at, 8);
                if (!ptr) break;
                const MetaBlock& b = m.block(meta_block_id(ptr));
                uint32_t off = meta_offset(ptr);
                if (off > b.data.size()) throw Error("meta: data block pointer outside its block");
                MetaLink l; l.kind = MetaLink::Kind::DataBlock; l.offset = (uint32_t)at; l.block_type = b.type;
                l.raw.assign(b.data.begin() + off, b.data.end());
                zero_pointer(at);
                obj.links.push_back(std::move(l));
                break;
            }
            case StructurePointer: {
                uint64_t ptr; std::memcpy(&ptr, obj.data.data() + at, 8);
                if (!ptr) break;
                MetaLink l; l.kind = MetaLink::Kind::Pointer; l.offset = (uint32_t)at;
                l.items.push_back(detach_object(m, ptr));
                zero_pointer(at);
                obj.links.push_back(std::move(l));
                break;
            }
            case Structure: {
                const MetaStruct* sub = describe(m, e.ref_key);
                if (!sub) throw Error("meta: no description for nested structure " + hash_name(e.ref_key));
                if (at + (size_t)sub->size > obj.data.size()) throw Error("meta: nested structure overruns its parent");
                walk(*sub, at);
                break;
            }
            case Array: {
                MetaArray a = Meta::read_array(obj.data.data() + at);
                if (e.ref_index < 0 || (size_t)e.ref_index >= info.entries.size()) throw Error("meta: array without element description");
                const MetaEntry& el = info.entries[e.ref_index];
                if (!a.pointer || !a.count) { break; }
                MetaLink l; l.offset = (uint32_t)at; l.count = a.count;
                if (el.type == Structure) {
                    const MetaStruct* sub = describe(m, el.ref_key);
                    if (!sub) throw Error("meta: no description for array element structure " + hash_name(el.ref_key));
                    l.kind = MetaLink::Kind::Structs; l.block_type = el.ref_key;
                    const uint8_t* p = m.at(a.pointer, (size_t)sub->size * a.count);
                    for (uint32_t i = 0; i < a.count; i++)
                        l.items.push_back(detach_object(m, el.ref_key, p + (size_t)i * sub->size, (size_t)sub->size * (a.count - i)));
                } else if (el.type == StructurePointer) {
                    l.kind = MetaLink::Kind::Pointers;
                    const uint8_t* p = m.at(a.pointer, 8ull * a.count);
                    for (uint32_t i = 0; i < a.count; i++) {
                        uint64_t ptr; std::memcpy(&ptr, p + 8ull * i, 8);
                        l.items.push_back(detach_object(m, ptr));
                    }
                } else {
                    size_t stride = primitive_stride(el.type);
                    if (!stride) throw Error("meta: unsupported array element type " + std::to_string(el.type));
                    l.kind = MetaLink::Kind::Primitives;
                    const uint8_t* p = m.at(a.pointer, stride * a.count);
                    l.raw.assign(p, p + stride * a.count);
                    l.block_type = m.type_at(a.pointer);
                }
                zero_pointer(at);
                obj.links.push_back(std::move(l));
                break;
            }
            default: break; // plain values live in `data`
            }
        }
    }
};

} // namespace

MetaObject detach_object(const Meta& m, uint32_t type, const uint8_t* instance, size_t available) {
    const MetaStruct* info = describe(m, type);
    if (!info) throw Error("meta: no description for structure " + hash_name(type));
    if (available < (size_t)info->size) throw Error("meta: structure " + hash_name(type) + " runs past its block");
    MetaObject o;
    o.type = type;
    o.data.assign(instance, instance + info->size);
    Detacher d{m, o};
    d.walk(*info, 0);
    return o;
}

MetaObject detach_object(const Meta& m, uint64_t pointer) {
    const MetaBlock& b = m.block(meta_block_id(pointer));
    uint32_t off = meta_offset(pointer);
    if (off > b.data.size()) throw Error("meta: pointer outside its block");
    return detach_object(m, b.type, b.data.data() + off, b.data.size() - off);
}

Bytes MetaBuilder::pack_object(const MetaObject& o) {
    Bytes bytes = o.data;
    for (auto& l : o.links) {
        if (l.offset + 8 > bytes.size()) throw Error("meta: link outside its object");
        uint8_t* at = bytes.data() + l.offset;
        auto put_array = [&](const MetaPtr& p, uint32_t count) {
            // keep a source file's capacity margin (some tools write strings with count + 1)
            MetaArray old = Meta::read_array(at);
            MetaArray a; a.pointer = p.pointer(); a.count = (uint16_t)count;
            a.capacity = old.capacity > old.count ? (uint16_t)(count + (old.capacity - old.count)) : a.count;
            std::memcpy(at, &a.pointer, 8);
            std::memcpy(at + 8, &a.count, 2);
            std::memcpy(at + 10, &a.capacity, 2);
        };
        switch (l.kind) {
        case MetaLink::Kind::String: {
            MetaPtr p = add_string(std::string(l.raw.begin(), l.raw.end()));
            put_array(p, (uint32_t)l.raw.size());
            break;
        }
        case MetaLink::Kind::Structs:
            put_array(add_object_array(l.block_type, l.items), (uint32_t)l.items.size());
            break;
        case MetaLink::Kind::Pointers:
            put_array(add_object_pointers(l.items), (uint32_t)l.items.size());
            break;
        case MetaLink::Kind::Primitives:
            put_array(add_item_array(l.block_type, l.raw, l.count), l.count);
            break;
        case MetaLink::Kind::DataBlock: {
            uint64_t p = add_data_block(l.raw, l.block_type).pointer();
            std::memcpy(at, &p, 8);
            break;
        }
        case MetaLink::Kind::Pointer: {
            uint64_t p = add_object(l.items.at(0)).pointer();
            std::memcpy(at, &p, 8);
            break;
        }
        }
    }
    return bytes;
}

MetaPtr MetaBuilder::add_object(const MetaObject& o) {
    Bytes b = pack_object(o);
    return add_item(o.type, b);
}
MetaPtr MetaBuilder::add_object_array(uint32_t type, std::span<const MetaObject> v) {
    if (v.empty()) return {};
    Bytes all;
    for (auto& o : v) { Bytes b = pack_object(o); all.insert(all.end(), b.begin(), b.end()); }
    return add_item_array(type, all, (uint32_t)v.size());
}
MetaPtr MetaBuilder::add_object_pointers(std::span<const MetaObject> v) {
    if (v.empty()) return {};
    std::vector<uint64_t> ptrs;
    for (auto& o : v) ptrs.push_back(add_object(o).pointer());
    return add_pointer_array(ptrs);
}

} // namespace rk
